with joined as (select src.id, src.customer_id, src.end_date, src.monthly_fee, d.city from subscriptions src left join customers d on src.customer_id = d.id where d.name not like '%Davi%'), matched as (select a.*, sub.id as subscription_id, sub.plan, sub.monthly_fee as subscription_monthly_fee from joined a left join subscriptions sub on a.customer_id = sub.customer_id and a.end_date between sub.start_date and sub.end_date), metrics as (select *, avg(monthly_fee) over (partition by city) as city_avg_monthly_fee, round(monthly_fee / sum(monthly_fee) over (partition by plan), 4) as monthly_fee_share, avg(subscription_monthly_fee) over (partition by year(end_date), plan order by subscription_id, id, subscription_id rows between 3 preceding and current row) as subscription_monthly_fee_avg_3 from matched), with_dims as (select s.id, s.customer_id, s.city, s.subscription_id, s.plan, s.subscription_monthly_fee, s.monthly_fee_share, s.subscription_monthly_fee_avg_3, b.email, b.name, b.segment from metrics s left join customers b on s.customer_id = b.id), remaining_keys as (select id, customer_id from with_dims except all select id, customer_id from subscriptions where monthly_fee <= 240), reconciled as (select s.* from with_dims s inner join remaining_keys k on s.id = k.id and s.customer_id = k.customer_id), stats as (select plan, case when monthly_fee_share >= 0.67 then 'PREMIUM' else 'STANDARD' end as monthly_fee_share_tier, count(*) filter (where city = 'Singapore') as singapore_rows, size(collect_set(segment)) as num_segments, avg(subscription_monthly_fee) filter (where city = 'Chiang Mai') as chiang_mai_avg_subscription_monthly_fee, sort_array(collect_set(plan)) as plan_list, sort_array(collect_set(plan)) as plan_list_2, round(sum(subscription_monthly_fee_avg_3) / nullif(count(case when segment = 'Consumer' then 1 end), 0), 2) as subscription_monthly_fee_avg_3_per_consumer, grouping(plan) as gid from reconciled group by cube (plan, case when monthly_fee_share >= 0.67 then 'PREMIUM' else 'STANDARD' end)) select plan, monthly_fee_share_tier, singapore_rows, num_segments, chiang_mai_avg_subscription_monthly_fee, plan_list_2, gid, case when plan rlike '^(enterprise|basic)$' then 'GROUP_A' else 'OTHER_ZONE' end as plan_zone from stats order by monthly_fee_share_tier desc nulls first;
